import{_ as e,o as a,c as o,af as s}from"./chunks/framework._zKnALF5.js";const g=JSON.parse('{"title":"快速入门","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),r={name:"guide/getting-started.md"};function d(n,t,i,h,l,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to &quot;快速入门&quot;">​</a></h1><p><strong>小游码匠</strong>（仓库名 <strong><code>xymj-colyseus-server</code></strong>）是在 <strong>Colyseus</strong> 之上实现的 <strong>约束型</strong> 服务端：TypeScript + Express，约定 JWT、匹配房、帧同步房、聊天房等开箱能力。下面按 <strong>最短路径</strong> 跑起来；原理与目录细节见侧栏其他页。</p><h2 id="_1-克隆并装依赖" tabindex="-1">1. 克隆并装依赖 <a class="header-anchor" href="#_1-克隆并装依赖" aria-label="Permalink to &quot;1. 克隆并装依赖&quot;">​</a></h2><p>在 <strong><code>xymj-colyseus-server</code></strong> 仓库根目录：</p><p><strong>（服务端代码）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>环境要求见 <a href="/guide/installation.html">安装指南</a>。</p><h2 id="_2-配环境并起服务" tabindex="-1">2. 配环境并起服务 <a class="header-anchor" href="#_2-配环境并起服务" aria-label="Permalink to &quot;2. 配环境并起服务&quot;">​</a></h2><p>复制并编辑 <code>.env.development</code>（MySQL、<strong>Redis</strong>（匹配/聊天队列需要）、<code>JWT_SECRET</code> 等），然后：</p><p><strong>（服务端代码）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>默认 <strong><code>http://localhost:2567</code></strong>（端口看 <code>PORT</code>）。</p><h2 id="_3-验证-http-与文档" tabindex="-1">3. 验证 HTTP 与文档 <a class="header-anchor" href="#_3-验证-http-与文档" aria-label="Permalink to &quot;3. 验证 HTTP 与文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>做什么</th><th>地址</th></tr></thead><tbody><tr><td>Swagger</td><td><code>http://localhost:2567/api-docs</code></td></tr><tr><td>框架介绍页（静态）</td><td><code>http://localhost:2567/</code></td></tr></tbody></table><p>用 Swagger 或现有账号接口拿到 <strong><code>token</code></strong>，后面进 Colyseus 房间要放在 options 里（约定见 <a href="/guide/jwt-room-auth.html">JWT 与房间鉴权</a> 第 3 节）。</p><h2 id="_4-浏览器里跑通匹配-推荐" tabindex="-1">4. 浏览器里跑通匹配（推荐） <a class="header-anchor" href="#_4-浏览器里跑通匹配-推荐" aria-label="Permalink to &quot;4. 浏览器里跑通匹配（推荐）&quot;">​</a></h2><p>打开 <strong><code>http://localhost:2567/MatchmakingDemo.html</code></strong>，填服务地址与 JWT，多开标签页可测 <strong><code>match:find</code> → <code>match:found</code> → 进 <code>game_room</code></strong>。参数含义与多人数玩法见 <a href="/scenarios/multi-scale-matchmaking.html">多 V 多自动匹配</a>。</p><h2 id="_5-接下来看什么" tabindex="-1">5. 接下来看什么 <a class="header-anchor" href="#_5-接下来看什么" aria-label="Permalink to &quot;5. 接下来看什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>文档</th></tr></thead><tbody><tr><td>环境变量全集</td><td><a href="/guide/configuration.html">配置说明</a></td></tr><tr><td>房间名、目录</td><td><a href="/guide/project-structure.html">项目结构</a></td></tr><tr><td>匹配 / Party 消息名</td><td><a href="/rooms/matchmaking.html">匹配与开房</a>、<a href="/reference/protocol.html">消息协议</a></td></tr><tr><td>Unity / Cocos / Godot 连本服务</td><td><a href="/engine/overview.html">游戏引擎接入</a></td></tr><tr><td>按玩法选型</td><td><a href="/scenarios/overview.html">应用场景概览</a></td></tr></tbody></table>',19)])])}const m=e(r,[["render",d]]);export{g as __pageData,m as default};
